YT='https://www.youtube.com/watch?v=keep_YT1234';CDN='https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js';cache=Path('/tmp/treino36-html2pdf.bundle.js')
