 row=picker.locator('[data-video-id="'+smith['id']+'"]').locator('..');row.locator('.gif-preview-eye').click();preview=page.locator('#movementPreview');expect(preview).to_be_visible();page.wait_for_function('document.querySelector("#movementPreview video").readyState>=2',timeout=20000);assert page.evaluate('localStorage.getItem("treinoAlunos")')==before;assert page.evaluate('previewLayouts.every(v=>Math.abs(v.before.height-v.after.height)<1&&Math.abs(v.before.y-v.after.y)<1)');preview.get_by_role('button').click();expect(preview).not_to_be_visible();row.locator('[data-video-id]').click();preview.get_by_role('button').click();expect(choice.locator('.pdf-gif-count')).to_have_text('1/2 GIFs associados');expect(choice.locator('input')).to_have_value(YT)
