 def export_links():
  count=page.evaluate('pdfWindows.length');page.locator('#downloadPdfBtn').click();page.wait_for_function('pdfWindows.length===%d&&pdfWindows.at(-1).url'%(count+1),timeout=30000);encoded=page.evaluate("async()=>btoa(Array.from(new Uint8Array(await pdfBlobs.get(pdfWindows.at(-1).url).arrayBuffer()),v=>String.fromCharCode(v)).join(''))")
  with fitz.open(stream=base64.b64decode(encoded),filetype='pdf') as doc:return [link.get('uri','') for p in doc for link in p.get_links()]
 include.uncheck();links=export_links();assert smith['url'] not in links and sumo['url'] not in links;assert any(parse_qs(urlparse(u).query).get('url')==[YT] for u in links)
 include.check();links=export_links();assert smith['url'] in links and sumo['url'] in links;assert any(parse_qs(urlparse(u).query).get('url')==[YT] for u in links)
